import psutil
import time

# Parent processes that should never spawn shells or scripting engines
SUSPICIOUS_PARENTS = {'nginx', 'apache2', 'httpd', 'iis', 'w3wp',
                      'outlook', 'winword', 'excel', 'powerpnt'}

# Child processes that indicate command execution
SHELL_CHILDREN = {'cmd.exe', 'powershell.exe', 'bash', 'sh',
                  'wscript.exe', 'cscript.exe', 'mshta.exe'}

def monitor_process_tree(interval=2):
    """Poll the process list and flag suspicious parent-child relationships."""
    while True:
        for proc in psutil.process_iter(['pid', 'name', 'ppid']):
            try:
                name = proc.info['name'].lower()
                if name not in SHELL_CHILDREN:
                    continue
                parent = psutil.Process(proc.info['ppid'])
                parent_name = parent.name().lower()
                if parent_name in SUSPICIOUS_PARENTS:
                    print(f"[ALERT] Suspicious spawn: {parent_name} "
                          f"(pid={proc.info['ppid']}) -> {name} "
                          f"(pid={proc.info['pid']})")
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                pass
        time.sleep(interval)

monitor_process_tree()

