package main

import (
	"fmt"
	"os"
	"os/exec"
	"runtime"
)

// Config carries per-run settings — target, scope, output path
type Config struct {
	OutputDir string
	DryRun    bool
}

// Result is what every technique returns
type Result struct {
	TechniqueID string
	Name        string
	Success     bool
	Output      string
	Error       string
}

// TechniqueFunc is the standard signature — every technique implements this
type TechniqueFunc func(cfg Config) Result

// T1057 — Process Discovery
func T1057_ProcessDiscovery(cfg Config) Result {
	res := Result{TechniqueID: "T1057", Name: "Process Discovery"}
	var cmd *exec.Cmd
	if runtime.GOOS == "windows" {
		cmd = exec.Command("tasklist")
	} else {
		cmd = exec.Command("ps", "aux")
	}
	out, err := cmd.Output()
	if err != nil {
		res.Error = err.Error()
		return res
	}
	res.Success = true
	res.Output = fmt.Sprintf("%d bytes of process list", len(out))
	return res
}

