package main

import (
	"fmt"
	"sync"
)

func RunTechniques(techniques []TechniqueFunc, cfg Config) []Result {
	results := make([]Result, len(techniques))
	var wg sync.WaitGroup

	for i, fn := range techniques {
		wg.Add(1)
		go func(idx int, technique TechniqueFunc) {
			defer wg.Done()
			results[idx] = technique(cfg)   // Each technique runs in its own goroutine
		}(i, fn)
	}

	wg.Wait()   // Block until all goroutines complete
	return results
}

func PrintSummary(results []Result) {
	passed, failed := 0, 0
	for _, r := range results {
		status := "PASS"
		if !r.Success {
			status = "FAIL"
			failed++
		} else {
			passed++
		}
		fmt.Printf("[%s] %s — %s\n", status, r.TechniqueID, r.Name)
	}
	fmt.Printf("\nTotal: %d passed, %d failed\n", passed, failed)
}

